<?= $this->section('title') ?>Existencias<?= $this->endSection() ?>
<?= $this->section('main') ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Existencias</h1><p class="text-body-secondary mb-0">Stock físico y alertas por material y bodega.</p></div><a class="btn btn-outline-primary" href="<?= url_to('inventory-movements') ?>">Movimientos</a></div>
<form class="row g-2 mb-3" method="get"><div class="col-md-4"><select class="form-select" name="warehouse_id"><option value="">Todas las bodegas</option><?php foreach ($warehouses as $warehouse): ?><option value="<?= esc((string) $warehouse['id']) ?>" <?= $warehouseId === (int) $warehouse['id'] ? 'selected' : '' ?>><?= esc($warehouse['name']) ?></option><?php endforeach ?></select></div><div class="col-auto"><button class="btn btn-outline-secondary">Filtrar</button></div></form>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Bodega</th><th>Código</th><th>Material</th><th class="text-end">Existencia</th><th class="text-end">Mínimo</th><th>Alerta</th><?php if ($showCosts): ?><th class="text-end">Valorado</th><th class="text-end">Valor</th><?php endif ?></tr></thead><tbody><?php foreach ($records as $record): ?><?php $low = (float) $record['quantity'] <= (float) $record['minimum_stock']; ?><tr><td><?= esc($record['warehouse_name']) ?></td><td class="font-monospace"><?= esc($record['code']) ?></td><td><?= esc($record['name']) ?></td><td class="text-end"><?= esc(number_format((float) $record['quantity'], 3, ',', '.')) ?> <?= esc($record['unit_symbol']) ?></td><td class="text-end"><?= esc(number_format((float) $record['minimum_stock'], 3, ',', '.')) ?></td><td><?= $low ? '<span class="badge text-bg-danger">Stock bajo</span>' : '<span class="badge text-bg-success">Normal</span>' ?></td><?php if ($showCosts): ?><td class="text-end"><?= esc(number_format((float) $record['valued_quantity'], 3, ',', '.')) ?></td><td class="text-end"><?= esc(number_format((float) ($record['total_value'] ?? 0), 2, ',', '.')) ?></td><?php endif ?></tr><?php endforeach ?><?php if ($records === []): ?><tr><td class="text-center text-body-secondary py-4" colspan="8">No hay materiales activos.</td></tr><?php endif ?></tbody></table></div></div>
<?= $this->endSection() ?>
